@push('scripts')<script>function bookingSlots(){return{date:'{{ $selectedDate ?: $dates[0]['value'] }}',time:'{{ $selectedTime }}',slots:[],loading:false,async load(d){this.date=d;this.time='';this.loading=true;try{const r=await fetch('{{ route('booking.slots') }}?date='+encodeURIComponent(d),{headers:{Accept:'application/json'}});const j=await r.json();if(!r.ok||!j.status)throw new Error(j.message||'Unable to load slots');const raw=j.data?.slots??j.data??[];this.slots=Array.isArray(raw)?raw.map(x=>typeof x==='string'?x:(x.time||x.label||x.start_time)).filter(Boolean):Object.values(raw).flat().map(x=>typeof x==='string'?x:(x.time||x.label||x.start_time)).filter(Boolean)}catch(e){this.slots=[]}finally{this.loading=false}}}}</script>@endpush
